Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_N = (1 << 19) + 5;
int N, K, MOD, MAX_VAL, popcnt[MAX_N], F[MAX_N];
int A[20][MAX_N], B[20][MAX_N], C[20][MAX_N];
long long MOD_SQ;
long long TMP[20][MAX_N];
long long FACT[MAX_N], INV_FACT[MAX_N];

long long mod_pow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

void precompute() {
    FACT[0] = 1;
    for (int i = 1; i <= MAX_VAL; ++i)
        FACT[i] = FACT[i-1] * i % MOD;
    INV_FACT[MAX_VAL] = mod_pow(FACT[MAX_VAL], MOD - 2);
    for (int i = MAX_VAL - 1; i >= 0; --i)
        INV_FACT[i] = INV_FACT[i+1] * (i+1) % MOD;
}

int next_power_of_two(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void fwht_transform(int *arr, int len, bool inverse = false) {
    static long long buffer[MAX_N];
    for (int i = 0; i < len; ++i) buffer[i] = arr[i];

    if (inverse) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    long long x = buffer[i + j];
                    long long y = buffer[i + j + step];
                    buffer[i + j + step] = (x - y) % MOD;
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    long long x = buffer[i + j];
                    long long y = buffer[i + j + step];
                    buffer[i + j + step] = (x + y) % MOD;
                }
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        arr[i] = (int)(buffer[i] % MOD);
        if (arr[i] < 0) arr[i] += MOD;
    }
}

inline void adjust_value(long long &x) {
    if (x >= MOD_SQ) x -= MOD_SQ;
}

void perform_multiply() {
    for (int i = 0; i <= 19; ++i) {
        memset(A[i], 0, sizeof(int[MAX_VAL + 1]));
        memset(TMP[i], 0, sizeof(long long[MAX_VAL + 1]));
    }

    for (int i = 0; i <= MAX_VAL; ++i)
        A[popcnt[i]][i] = F[i];

    for (int i = 0; i <= 19; ++i)
        fwht_transform(A[i], MAX_VAL + 1);

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= MAX_VAL; ++s)
                adjust_value(TMP[q + l][s] += 1LL * A[q][s] * B[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= MAX_VAL; ++s)
            C[q][s] = (int)(TMP[q][s] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht_transform(C[i], MAX_VAL + 1, true);

    for (int i = 0; i <= MAX_VAL; ++i)
        F[i] = C[popcnt[i]][i];
}

void perform_square() {
    static int temp[20][MAX_N];
    for (int i = 0; i <= 19; ++i)
        memset(TMP[i], 0, sizeof(long long[MAX_VAL + 1]));

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= MAX_VAL; ++s)
                adjust_value(TMP[q + l][s] += 1LL * B[q][s] * B[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= MAX_VAL; ++s)
            temp[q][s] = (int)(TMP[q][s] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht_transform(temp[i], MAX_VAL + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(B[i], 0, sizeof(int[MAX_VAL + 1]));

    for (int i = 0; i <= MAX_VAL; ++i)
        B[popcnt[i]][i] = temp[popcnt[i]][i];

    for (int i = 0; i <= 19; ++i)
        fwht_transform(B[i], MAX_VAL + 1);
}

int main() {
    scanf("%d%d%d", &N, &K, &MOD);
    MOD_SQ = 1LL * MOD * MOD;

    if (N & 1) {
        printf("%lld", mod_pow(K, N));
        return 0;
    }

    F[0] = 1;
    MAX_VAL = next_power_of_two(N + 1) - 1;
    precompute();

    for (int i = 0; i <= MAX_VAL; ++i)
        popcnt[i] = __builtin_popcount(i);

    for (int i = 0; i <= MAX_VAL; ++i)
        B[popcnt[i]][i] = INV_FACT[i];

    for (int i = 0; i <= 19; ++i)
        fwht_transform(B[i], MAX_VAL + 1);

    int original_K = K;
    while (K) {
        if (K & 1) perform_multiply();
        K >>= 1;
        if (K) perform_square();
    }

    printf("%lld", (mod_pow(original_K, N) - FACT[N] * F[N] % MOD + MOD) % MOD);
    return 0;
}
